example.code:
# app/services/service_result.rb — the ONLY definition in the repo
class ServiceResult
  attr_reader :data, :error, :details

  def self.success(data: nil) = new(success: true, data: data)
  def self.failure(error:, details: nil) = new(success: false, error: error, details: details)

  def initialize(success:, data: nil, error: nil, details: nil)
    @success = success
    @data    = data
    @error   = error
    @details = details
  end

  def success? = @success
  def failure? = !@success
end
